namespace sv_b7b70fd173d84386a0a6537cd45af03c.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// Because all InteractiveServer components share one circuit (and one DI scope),
/// every interactive component on every page sees the same instance.
/// </summary>
public sealed class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    /// <summary>Raised whenever theme or accent color changes.</summary>
    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }
}

// Applies theme state to the document so that even statically-rendered HTML
// picks up the current theme via CSS custom properties / data attributes.
export function applyTheme(theme, accentColor) {
    document.documentElement.setAttribute('data-bs-theme', theme);
    document.documentElement.style.setProperty('--app-accent-color', accentColor);
}

@* Interactive island embedded in the static layout.
   On first render and on every theme change it pushes the current values
   into the document via JS so that CSS custom properties / data-attributes
   apply to the entire page — including static HTML. *@

@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme-interop.js");
        }

        if (_module is not null)
        {
            var cssTheme = ThemeService.CurrentTheme switch
            {
                Theme.Dark => "dark",
                Theme.Light => "light",
                _ => "auto"
            };
            await _module.InvokeVoidAsync("applyTheme", cssTheme, ThemeService.AccentColor);
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnChange -= HandleThemeChanged;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

@* Small interactive island in the header that shows the current theme. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleChange;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div class="btn-group d-flex" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                var isActive = ThemeService.CurrentTheme == theme;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        style="@(isActive ? $"background-color:{ThemeService.AccentColor};border-color:{ThemeService.AccentColor}" : "")"
                        @onclick="() => ThemeService.SetTheme(theme)">
                    @theme
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold" for="accent">Accent Color</label>
        <input id="accent" type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentChanged" />
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleChange;
}

