@* Interactive island embedded in the static layout.
   On first render and on every theme change it pushes the current values
   into the document via JS so that CSS custom properties / data-attributes
   apply to the entire page — including static HTML. *@

@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme-interop.js");
        }

        if (_module is not null)
        {
            var cssTheme = ThemeService.CurrentTheme switch
            {
                Theme.Dark => "dark",
                Theme.Light => "light",
                _ => "auto"
            };
            await _module.InvokeVoidAsync("applyTheme", cssTheme, ThemeService.AccentColor);
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnChange -= HandleThemeChanged;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

