@* Small interactive island in the header that shows the current theme. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleChange;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div class="btn-group d-flex" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                var isActive = ThemeService.CurrentTheme == theme;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        style="@(isActive ? $"background-color:{ThemeService.AccentColor};border-color:{ThemeService.AccentColor}" : "")"
                        @onclick="() => ThemeService.SetTheme(theme)">
                    @theme
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold" for="accent">Accent Color</label>
        <input id="accent" type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentChanged" />
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleChange() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= HandleChange;
}

